package de.lazytv.pro.catalog;
import org.junit.Test;import static org.junit.Assert.*;
public class ManagedSheetCatalogSourceTest {
 private final ManagedSheetCatalogSource.Server server=new ManagedSheetCatalogSource.Server("SERVER_09","Fixture","fixture");
 private String csv(String rows){return "ID,SOURCE_ID,SERVER_ID,COUNTRY_CODE,CATEGORY,NAME,STREAM_URL_CMD,STATUS\n"+rows;}
 @Test public void refreshUpsertsStableSourceAndRejectsOtherServer()throws Exception {
  Catalog c=ManagedSheetCatalogSource.parse(server,"LIVE",csv("row1,7,SERVER_09,DE,News,First,http://fixture.invalid?token=old,ACTIVE\nrow2,7,SERVER_09,DE,News,Updated,http://fixture.invalid?token=fresh,ACTIVE\nrow3,7,SERVER_10,DE,News,Wrong,http://fixture.invalid,ACTIVE\n"));assertEquals(1,c.items.size());assertEquals("SERVER_09|7",c.items.get(0).id);assertEquals("Updated",c.items.get(0).name);assertTrue(c.items.get(0).streamUrl.endsWith("fresh"));
 }
 @Test public void cinemaAndNetflixLinearChannelsNeverBecomeMovies()throws Exception {for(String tab:new String[]{"LIVE","24_7"}){Catalog c=ManagedSheetCatalogSource.parse(server,tab,csv("row,7,SERVER_09,AL,NETFLIX CINEMA,Linear,http://fixture.invalid,ACTIVE\n"));assertEquals(CatalogType.LIVE,c.items.get(0).type);assertEquals(tab,c.items.get(0).meta("managed_tab"));}}
 @Test public void originalCommandAndQuotedNewlinesSurvive()throws Exception {Catalog c=ManagedSheetCatalogSource.parse(server,"LIVE",csv("row,7,SERVER_09,DE,News,\"A, B\nC\",ffmpeg http://localhost/ch/7_,ACTIVE\n"));assertEquals("A, B\nC",c.items.get(0).name);assertEquals("ffmpeg http://localhost/ch/7_",c.items.get(0).meta("stalker_original_cmd"));}
 @Test public void inactiveAndEmptyCatalogsStayEmpty()throws Exception {assertTrue(ManagedSheetCatalogSource.parse(server,"LIVE",csv("row,7,SERVER_09,DE,News,Off,http://fixture.invalid,OFF\n")).isEmpty());assertTrue(ManagedSheetCatalogSource.parse(server,"LIVE",csv("")).isEmpty());}
 @Test public void wrongVodAndSeriesImportsStayLive()throws Exception {for(String tab:new String[]{"VOD","SERIES"}){Catalog c=ManagedSheetCatalogSource.parse(server,tab,csv("row,7,SERVER_09,AL,CINEMA,Linear,ffmpeg http://localhost/ch/7_,ACTIVE\n"));assertEquals(CatalogType.LIVE,c.items.get(0).type);assertEquals("LIVE",c.items.get(0).meta("managed_tab"));}assertFalse(ManagedSheetCatalogSource.linearCommand("http://fixture.invalid/movie/user/pass/7.mp4"));}
 @Test public void typedTabsAreExplicit()throws Exception {assertEquals(CatalogType.MOVIES,ManagedSheetCatalogSource.parse(server,"VOD",csv("row,7,SERVER_09,DE,Film,Movie,http://fixture.invalid,ACTIVE\n")).items.get(0).type);try{ManagedSheetCatalogSource.parse(server,"Sheet1",csv(""));fail();}catch(CatalogException expected){}}
 @Test public void kosovoEvidenceOverridesOldAlbaniaWithoutChangingSharedResolver(){assertEquals("XK",ManagedCountryResolver.resolve("AL","Albania","Kosovo News","RTK"));assertEquals("AL",ManagedCountryResolver.resolve("AL","Albania","Albania + Kosovo","News"));assertEquals("DE",ManagedCountryResolver.resolve("","","DE | Sport","Channel"));assertEquals("OTHER",ManagedCountryResolver.resolve("","","Unknown","Channel"));}
 @Test public void seriesParentsCannotBePlayedAndEpisodesNeedExplicitStructure()throws Exception {
  String body="ID,SOURCE_ID,SERVER_ID,NAME,STREAM_URL_CMD,SERIES_ID,SEASON,EPISODE,EPISODE_TITLE\nparent,1,SERVER_09,Fixture,,10,,,\nepisode,2,SERVER_09,Fixture,http://fixture.invalid/series/u/p/2.mp4,10,2,3,Episode Three\n";
  Catalog c=ManagedSheetCatalogSource.parse(server,"SERIES",body);assertEquals(2,c.items.size());Series parent=null;Episode episode=null;for(StreamItem i:c.items){if(i instanceof Series)parent=(Series)i;if(i instanceof Episode)episode=(Episode)i;}assertNotNull(parent);assertNotNull(episode);assertEquals("",parent.streamUrl);assertEquals(parent.id,episode.seriesId);assertEquals(2,episode.seasonNumber);assertEquals(3,episode.episodeNumber);assertFalse(de.lazytv.pro.player.PlayerContentPolicy.playable(parent));assertTrue(de.lazytv.pro.player.PlayerContentPolicy.playable(episode));
 }
 @Test public void registryUsesServerIdsDespiteRenamesAndDuplicateDisplayNames()throws Exception {
  String body="ID,Emri,Aktiv,Spreadsheet_ID,Sheet_Name\nSERVER_09,Renamed,TRUE,fixture9,LIVE\nSERVER_10,Renamed,TRUE,fixture10,LIVE\nSERVER_11,Off,FALSE,fixture11,LIVE\n";
  java.util.Map<String,ManagedSheetCatalogSource.Server> registry=ManagedSheetCatalogSource.registry(body);assertEquals(2,registry.size());assertEquals("fixture9",registry.get("SERVER_09").sheet);assertEquals("fixture10",registry.get("SERVER_10").sheet);assertFalse(registry.containsKey("Renamed"));
 }
 @Test public void actualMasterCountryMetadataAndRegionalGroupsRemainUsable(){String[] names={"SHQIPERIA","KOSOVA","MAQEDONIA E VERIUT","MALI I ZI","SERBIA","BOSNIA","KROACIA","TURQIA","ITALIA","GJERMANIA"},codes={"AL","XK","MK","ME","RS","BA","HR","TR","IT","DE"};for(int n=0;n<names.length;n++)assertEquals(names[n],codes[n],ManagedCountryResolver.resolve("",names[n],"General","Fixture"));assertEquals("EXYU",ManagedCountryResolver.resolve("","EXYU","Cinema","Fixture"));assertEquals("EXYU",ManagedCountryResolver.groups(java.util.Collections.singletonList(new Category("id","Cinema",CatalogType.LIVE,"EXYU"))).get(0).key);}
 @Test public void mixedGenreStillAllowsClearKosovoChannelButKeepsDirectOtherProviderCountries(){assertEquals("XK",ManagedCountryResolver.resolve("AL","Albania","Albania + Kosovo","Kosovo TV"));assertEquals("AL",ManagedCountryResolver.resolve("AL","Albania","Shqipëri / Kosovë","Fixture"));assertEquals("DE",ManagedCountryResolver.resolve("DE","Germany","Kosovo News","Fixture"));}
 @Test public void providerGenreMovesLinearLiveIntoTwentyFourWithoutMakingVod()throws Exception {Catalog linear=ManagedSheetCatalogSource.parse(server,"LIVE",csv("row,7,SERVER_09,AL,24/7 Cinema,Linear,http://fixture.invalid/live/7.ts,ACTIVE\n"));assertEquals("24_7",linear.items.get(0).meta("managed_tab"));assertEquals(CatalogType.LIVE,linear.items.get(0).type);Catalog movie=ManagedSheetCatalogSource.parse(server,"VOD",csv("row,7,SERVER_09,AL,24/7 Cinema,Movie,http://fixture.invalid/movie/u/p/7.mp4,ACTIVE\n"));assertEquals(CatalogType.MOVIES,movie.items.get(0).type);assertEquals("VOD",movie.items.get(0).meta("managed_tab"));}
 @Test public void signedUrlAloneDoesNotTurnMovieIntoLiveAndContentKindsDoNotOverwrite()throws Exception {
  String signed="http://fixture.invalid/play/file.php?mac=00%3A11%3A22%3A33%3A44%3A55&stream=7&play_token=fixture";
  Catalog live=ManagedSheetCatalogSource.parse(server,"LIVE",csv("row,7,SERVER_09,AL,News,Fixture,"+signed+",ACTIVE\n"));Catalog movie=ManagedSheetCatalogSource.parse(server,"VOD",csv("row,7,SERVER_09,AL,Movies,Fixture,"+signed+",ACTIVE\n"));assertEquals(CatalogType.MOVIES,movie.items.get(0).type);ManagedSheetCatalogSource.merge(live,movie);assertEquals(2,live.items.size());java.util.Map<String,StreamItem> references=new java.util.HashMap<>();StreamItem channel=live.items.get(0);references.put(ManagedSheetCatalogSource.referenceKey(channel),channel);Catalog traced=ManagedSheetCatalogSource.parse(server,"VOD",csv("other,99,SERVER_09,AL,Movies,Fixture,"+signed+",ACTIVE\n"),references);assertEquals(CatalogType.LIVE,traced.items.get(0).type);assertEquals(channel.id,traced.items.get(0).id);
 }
 @Test public void movieFreshLinkUsesConfirmedProviderVodCommand()throws Exception {
  String signed="http://fixture.invalid/play/file.php?mac=00%3A11%3A22%3A33%3A44%3A55&stream=7&play_token=fixture";java.util.Map<String,String> metadata=new java.util.HashMap<>();metadata.put("managed_server","SERVER_09");StreamItem row=new StreamItem("SERVER_09|7","Fixture","cat","",signed,"",CatalogType.MOVIES,java.util.Collections.emptyList(),metadata);Catalog provider=new Catalog();provider.items.add(new StreamItem("7","Fixture","cat","","ffmpeg http://localhost/media/file_7.mp4","",CatalogType.MOVIES));StreamItem verified=ManagedStalkerLinkResolver.verifiedMovie(row,provider,ServerTenPlaybackResolver.reference(row));assertEquals("ffmpeg http://localhost/media/file_7.mp4",verified.meta("stalker_original_cmd"));assertFalse(verified.meta("stalker_original_cmd").contains("localhost/ch/"));
 }
}
